// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(user != address(0) && user != address(c));
        amount = bound(amount, 1, 1e18);

        // Deposit
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();

        // Withdraw (may fail because user is a contract without receive)
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // The invariant: the user's credit should be 0 if the withdrawal succeeded, otherwise amount
        uint256 expected = success ? 0 : amount;
        assertTrue(c.credit(user) == expected, "Credit mismatch");
    }
}

