pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 withdrawOrder) public {
        vm.assume(sender != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        vm.deal(sender, depositAmount * 2);

        // Deposit from sender
        vm.prank(sender);
        c.deposit{value: depositAmount}();

        // Get credit for sender and total balance after deposit
        uint256 creditAfterDeposit = c.credit(sender);
        uint256 balanceAfterDeposit = address(c).balance;

        // Withdraw all for sender
        vm.prank(sender);
        c.withdrawAll();

        // Get credit for sender and total balance after withdrawal
        uint256 creditAfterWithdrawal = c.credit(sender);
        uint256 balanceAfterWithdrawal = address(c).balance;

        // The invariant: total balance equals sum of all credits (only sender has credit)
        // After deposit: balance should equal credit for sender
        assertTrue(balanceAfterDeposit == creditAfterDeposit, "Balance should equal credit after deposit");
        // After withdrawal: balance should be at least unchanged (no credit left)
        // For reference: credit becomes 0, balance = balanceAfterDeposit - depositAmount (already subtracted)
        // For mutant: credit becomes 1, but balance was correctly reduced, so balance < credit
        assertTrue(balanceAfterWithdrawal >= creditAfterWithdrawal, "Balance should be >= credit after withdrawal");
    }
}

